import{_t as e,it as t,n,rt as r}from"./chunks/framework.Ke88N3OB.js";var i=JSON.parse(`{"title":"@pumpkin-plugins/update-check","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/tools/update-check/README.md"},"headers":[],"relativePath":"tools/update-check/README.md","filePath":"tools/update-check/README.md","lastUpdated":1792508807000}`),a={name:`tools/update-check/README.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="pumpkin-plugins-update-check" tabindex="-1">@pumpkin-plugins/update-check <a class="header-anchor" href="#pumpkin-plugins-update-check" aria-label="Permalink to “@pumpkin-plugins/update-check”">​</a></h1><p><a href="https://www.npmjs.com/package/@pumpkin-plugins/update-check" target="_blank" rel="noreferrer"><img src="https://img.shields.io/npm/dt/%40pumpkin-plugins%2Fupdate-check" alt="npm downloads"></a><a href="https://www.npmjs.com/package/@pumpkin-plugins/update-check" target="_blank" rel="noreferrer"><img src="https://img.shields.io/npm/v/%40pumpkin-plugins%2Fupdate-check?label=latest%20release" alt="latest npm release"></a><a href="https://www.npmjs.com/package/@pumpkin-plugins/update-check" target="_blank" rel="noreferrer"><img src="https://img.shields.io/npm/l/%40pumpkin-plugins%2Fupdate-check" alt="npm license"></a></p><p>Checks a plugin&#39;s current version against Pumpkin Market over Pumpkin&#39;s WASI HTTP host. The registration helper starts a non-blocking request after plugin loading when given a scheduler.</p><div class="language-ts"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { registerPluginWithUpdates } </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@pumpkin-plugins/update-check&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">registerPluginWithUpdates</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(plugin, info, { schedule });</span></span></code></pre></div><p>The plugin must request the <code>http</code> WASI capability and the server must grant <code>http.outbound</code>. The scheduler defers the initial request and dispatches follow-up polls through the plugin&#39;s task handler. The scheduler must run callbacks in a later task, never inline. Automatic checks do not block plugin startup or server ticks.</p><p>Asynchronous requests time out after 15 seconds. Response bodies larger than 64 KiB are rejected.</p><p>A failed update request is logged and does not interrupt plugin loading. <code>checkMarketUpdate</code> remains available for direct checks with an injected synchronous JSON request function, which is useful for deterministic tests. The <code>request</code> registration option takes the same kind of function in place of the scheduled request. It runs synchronously inside <code>onLoad</code> and blocks plugin loading, so use it only in tests. <code>requestMarketJsonAsync</code> exposes the same non-blocking transport for direct use. The synchronous <code>requestMarketJson</code> transport blocks and must not be called during plugin loading or server ticks. <code>marketplaceUrl</code> overrides the Market base URL for registration and direct version checks.</p><p>When Market returns optional <code>release_notes</code>, the checker converts its Markdown to plain text for the update notice. The current Market check endpoint does not return this field; a Market API update must add it before plugins can show changelogs.</p><p>For the server capability and registration setup, see the <a href="/pumpkin-plugins/guides/plugin-updates">plugin updates guide</a>.</p><p>See the <a href="https://filiphsps.github.io/pumpkin-plugins/tools/update-check/docs/" target="_blank" rel="noreferrer">tool guide</a> and <a href="https://filiphsps.github.io/pumpkin-plugins/api/tools/@pumpkin-plugins/update-check/" target="_blank" rel="noreferrer">API reference</a> on the documentation site.</p>`,10)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};